import { operation } from "@tinker/core";
import { z } from "zod";
import { auth } from "@/lib/tinker.server";

/** ADR 0103's named protocol exception mounts better-auth's third-party HTTP handler. */
export const handleAuth = operation({
  label: "handleAuth",
  input: z.instanceof(Request),
  depends: { auth },
  run: async ({ auth }, ctx) => auth.handler(ctx.input),
});

import { resource } from "@tinker/core";
import { transferResponseBodyOwnership } from "@tanstack/react-start/server";
/** Retains request work until the consumer ends, fails, or cancels the body. */
export const responseBodies = resource({
  label: "start.responseBodies",
  target: "scope",
  factory: (_deps, ctx) => {
    const readers = new Set<{
      reader: ReadableStreamDefaultReader<Uint8Array>;
      finish: (graceful: boolean) => Promise<void>;
      cancelled: boolean;
    }>();
    ctx.defer(async () => {
      const results = await Promise.allSettled(
        [...readers].map(async (owned) => {
          owned.cancelled = true;
          readers.delete(owned);
          const ended = await Promise.allSettled([owned.reader.cancel(), owned.finish(false)]);
          for (const result of ended) if (result.status === "rejected") throw result.reason;
        }),
      );
      for (const result of results) if (result.status === "rejected") throw result.reason;
    });
    return {
      async hold(
        response: Response,
        finish: (graceful: boolean) => Promise<void>,
      ): Promise<Response> {
        if (response.body === null) {
          await finish(true);
          return response;
        }
        const reader = response.body.getReader();
        const owned = { reader, finish, cancelled: false };
        readers.add(owned);
        const body = new ReadableStream<Uint8Array>({
          async pull(controller) {
            try {
              const part = await reader.read();
              if (part.done) {
                readers.delete(owned);
                await finish(!owned.cancelled);
                if (!owned.cancelled) controller.close();
              } else if (!owned.cancelled) controller.enqueue(part.value);
            } catch (error) {
              readers.delete(owned);
              await finish(false);
              if (!owned.cancelled) controller.error(error);
            }
          },
          async cancel(reason) {
            owned.cancelled = true;
            readers.delete(owned);
            const results = await Promise.allSettled([finish(false), reader.cancel(reason)]);
            for (const result of results) {
              if (result.status === "rejected") throw result.reason;
            }
          },
        });
        return transferResponseBodyOwnership(
          response,
          new Response(body, {
            status: response.status,
            statusText: response.statusText,
            headers: response.headers,
          }),
        );
      },
    };
  },
});

import type { PgAsyncDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
export declare namespace Database {
  type Handle = PgAsyncDatabase<PgQueryResultHKT> & {
    listen: (wake: () => void, disconnected: () => void) => Promise<() => void | Promise<void>>;
  };
  type Transaction = Parameters<Parameters<Handle["transaction"]>[0]>[0];
}

import { extension } from "@tinker/core";
import { migrate } from "@/lib/tinker.server";
export const setup = extension({
  label: "backend.setup",
  hooks: {
    async start(event) {
      await event.next();
      await event.scope.run(migrate);
    },
  },
});

import { resource } from "@tinker/core";
import type { Database } from "./database.ts";
import type { Sync } from "../sync.ts";
import { raise } from "../errors.ts";
/** A stream row stays locked until its records and events commit together. */
export const eventHistory = resource({
  label: "sync.history",
  factory: async () => {
    const [{ eq, sql }, { stream, event, execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./sync.schema.ts"),
    ]);
    return {
      async lock(tx: Database.Transaction, id: string) {
        await tx.insert(stream).values({ id }).onConflictDoNothing();
        const row = (await tx.select().from(stream).where(eq(stream.id, id)).for("update")).at(0);
        if (!row) raise("StreamMissing", {});
        return row.revision;
      },
      async find(tx: Database.Transaction, id: string, owner: string) {
        const row = (await tx.select().from(execution).where(eq(execution.id, id))).at(0);
        if (row && row.stream !== owner) raise("StreamDenied", {});
        return row;
      },
      async append(
        tx: Database.Transaction,
        owner: string,
        executionId: string,
        payloads: Sync.Payload[],
      ) {
        const row = (
          await tx
            .update(stream)
            .set({ revision: sql`${stream.revision} + ${payloads.length}` })
            .where(eq(stream.id, owner))
            .returning()
        ).at(0);
        if (!row) raise("StreamMissing", {});
        await tx.insert(event).values(
          payloads.map((payload, offset) => ({
            stream: owner,
            revision: row.revision - payloads.length + offset + 1,
            executionId,
            payload,
          })),
        );
        for (const payload of payloads) {
          if (payload.kind === "result")
            await tx
              .update(execution)
              .set({ result: payload.result })
              .where(eq(execution.id, executionId));
        }
      },
    };
  },
});

import { tag } from "@tinker/core";
/** Only request wiring and auth borrow the raw headers; app operations use principal. */
export const requestHeaders = tag<Headers>({ label: "request.headers" });

import { operation, resource } from "@tinker/core";
import { z } from "zod";
import { raise } from "../errors.ts";
import { httpBackend } from "../http-backend.ts";
import { backendStop, requestStop } from "./lifetime.ts";

const requestShape = z
  .strictObject({
    url: z.url({ protocol: /^https?$/ }),
    method: z
      .string()
      .regex(/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/)
      .toUpperCase(),
    headers: z.record(z.string(), z.string()).optional(),
    body: z.string().optional(),
  })
  .brand<"HttpRequest">();

/** Backend stop and request end abort HTTP before graceful shutdown joins work.
 * A direct graceful close without an aborted stop tag cannot stop a pending wait:
 * Core has no session close-start hook. Forced close and resource cleanup still abort. */
export const http = resource({
  label: "http",
  target: "session",
  depends: {
    send: httpBackend,
    backendStop: backendStop.optional,
    requestStop: requestStop.optional,
  },
  factory: ({ send, backendStop, requestStop }, ctx) => {
    const stop = new AbortController();
    ctx.defer(() => stop.abort());
    return {
      async send(url: string, init: RequestInit & { signal: AbortSignal }) {
        const signal = AbortSignal.any([
          init.signal,
          stop.signal,
          ...(backendStop.present ? [backendStop.value] : []),
          ...(requestStop.present ? [requestStop.value] : []),
        ]);
        signal.throwIfAborted();
        const response = await send(url, { ...init, signal });
        return {
          status: response.status,
          headers: Object.fromEntries(
            Array.from(response.headers, ([name, value]): [string, string[]] => [
              name,
              name === "set-cookie" ? response.headers.getSetCookie() : [value],
            ]),
          ),
          body: await response.text(),
        };
      },
    };
  },
});

/** HTTP statuses are results; only sending or reading failures raise HttpRequestFailed. */
export const httpRequest = operation({
  label: "http.request",
  input: requestShape,
  depends: { http },
  run: ({ http }, ctx) => {
    const { url, method, headers, body } = ctx.input;
    const path = new URL(url).pathname;
    return ctx.obs.child(`http ${method} ${path}`, async (span) => {
      if (span) {
        span.attributes["http.request.method"] = method;
        span.attributes["url.path"] = path;
      }
      try {
        const response = await http.send(url, { method, headers, body, signal: ctx.signal });
        if (span) span.attributes["http.response.status_code"] = response.status;
        return response;
      } catch (cause) {
        ctx.signal.throwIfAborted();
        const failureShape = z.object({
          name: z.string().optional().catch(undefined),
          code: z.union([z.string(), z.number()]).optional().catch(undefined),
          cause: z.unknown().optional(),
        });
        const failure = failureShape.safeParse(cause);
        if (!failure.success) raise("HttpRequestFailed", { method, path });
        const nested = failureShape.safeParse(failure.data.cause);
        const details = nested.success ? nested.data : failure.data;
        raise("HttpRequestFailed", {
          method,
          path,
          cause: {
            name: details.name ?? failure.data.name,
            code: details.code ?? failure.data.code,
          },
        });
      }
    });
  },
});

export { startRequests } from "../start.ts";
export { readResult } from "./result.server.ts";
export { responseBodies } from "./body.server.ts";
export { openSync, eventStream } from "./stream.ts";
export { notifications } from "./notifications.ts";

export { browserTelemetry, receiveTelemetry, telemetryOrigin } from "../telemetry/ingest.server.ts";

export { backendStop, requestStop } from "./lifetime.ts";
export { http, httpRequest } from "./http.ts";
export { httpBackend } from "../http-backend.ts";

import { tag } from "@tinker/core";
/** Original host signals end HTTP, telemetry bodies, and sync before graceful Core shutdown joins requests. */
export const backendStop = tag<AbortSignal>({ label: "lifetime.backendStop" });
export const requestStop = tag<AbortSignal>({ label: "lifetime.requestStop" });

import { resource } from "@tinker/core";
import { database } from "@/lib/tinker.server";
import { raise } from "../errors.ts";
/** One native listener wakes all request subscribers; reconnect replaces a broken listener. */
export const notifications = resource({
  label: "sync.notifications",
  depends: { database },
  factory: async ({ database }, ctx) => {
    let revision = 0;
    let broken = false;
    let connection:
      | Promise<
          | { kind: "connected"; close: () => void | Promise<void> }
          | { kind: "failed"; error: unknown }
        >
      | undefined;
    const watchers = new Set<{
      opened: NonNullable<typeof connection>;
      closed: boolean;
      disconnected?: () => void;
      waiting?: ReturnType<typeof Promise.withResolvers<void>>;
    }>();
    const wake = () => {
      revision += 1;
      for (const subscriber of watchers) {
        if (broken || subscriber.opened !== connection) subscriber.disconnected?.();
        subscriber.waiting?.resolve();
      }
    };
    const listenerFailed = () => {
      broken = true;
      wake();
    };
    ctx.defer(async () => {
      broken = true;
      wake();
      const current = await connection;
      if (current?.kind === "connected") await current.close();
    });
    return {
      async subscribe(disconnected?: () => void) {
        if (!connection || broken) {
          const previous = connection;
          broken = false;
          connection = Promise.resolve().then(async () => {
            const old = await previous;
            if (old?.kind === "connected") await old.close();
            try {
              return {
                kind: "connected" as const,
                close: await database.listen(wake, listenerFailed),
              };
            } catch (error) {
              broken = true;
              return { kind: "failed" as const, error };
            }
          });
        }
        const opened = connection;
        const connected = await opened;
        if (connected.kind === "failed") throw connected.error;
        if (broken || opened !== connection) raise("StreamDisconnected", {});
        const subscriber = { opened, closed: false, disconnected };
        watchers.add(subscriber);
        return subscriber;
      },
      revision() {
        return revision;
      },
      ended(subscriber: { opened: NonNullable<typeof connection>; closed: boolean }) {
        return subscriber.closed || broken || subscriber.opened !== connection;
      },
      close(subscriber: {
        opened: NonNullable<typeof connection>;
        closed: boolean;
        waiting?: ReturnType<typeof Promise.withResolvers<void>>;
        disconnected?: () => void;
      }) {
        subscriber.closed = true;
        watchers.delete(subscriber);
        subscriber.waiting?.resolve();
      },
      async wait(
        subscriber: {
          opened: NonNullable<typeof connection>;
          closed: boolean;
          waiting?: ReturnType<typeof Promise.withResolvers<void>>;
        },
        after: number,
        signal: AbortSignal,
      ) {
        if (subscriber.closed || broken || after !== revision || signal.aborted) return;
        const changed = Promise.withResolvers<void>();
        subscriber.waiting = changed;
        const notify = () => changed.resolve();
        signal.addEventListener("abort", notify, { once: true });
        try {
          await changed.promise;
        } finally {
          signal.removeEventListener("abort", notify);
          subscriber.waiting = undefined;
        }
      },
    };
  },
});

import { resource } from "@tinker/core";
import { backendStop, requestStop } from "./lifetime.ts";

/** The request owns the reader; its route borrows it until all body checks finish. */
export const requestBody = resource({
  label: "request.body",
  target: "session",
  depends: { backendStop, requestStop },
  factory: ({ backendStop, requestStop }, ctx) => {
    const signal = AbortSignal.any([backendStop, requestStop, ctx.signal]);
    let reader: ReadableStreamDefaultReader<Uint8Array<ArrayBuffer>> | undefined;
    let cancellation: Promise<void> | undefined;
    const cancel = () => {
      cancellation ??= reader?.cancel();
    };
    signal.addEventListener("abort", cancel, { once: true });
    const release = async () => {
      signal.removeEventListener("abort", cancel);
      if (signal.aborted) cancel();
      await cancellation;
      reader?.releaseLock();
      reader = undefined;
    };
    ctx.defer(release);
    return {
      signal,
      open(body: ReadableStream<Uint8Array<ArrayBuffer>>) {
        reader = body.getReader();
        if (signal.aborted) cancel();
        return reader;
      },
      release,
    };
  },
});

import type { RunResult } from "@tinker/core";
import { raise } from "../errors.ts";
/** HTTP boundaries handle a settled failure without failing the server root.
 * @param result - From a settled boundary call; why: return its value or raise its failure.
 */
export function readResult<T>(result: RunResult<T>): T {
  if (result.status === "failed") throw result.error;
  if (result.status === "cancelled") raise("Cancelled", {});
  return result.value;
}

import { z } from "zod";
import { raise } from "../errors.ts";
const telemetrySettings = z.object({
  VICTORIA_TRACES_URL: z
    .url({ protocol: /^https?$/ })
    .default("http://127.0.0.1:10428/insert/opentelemetry/v1/traces"),
  VICTORIA_LOGS_URL: z
    .url({ protocol: /^https?$/ })
    .default("http://127.0.0.1:9428/insert/jsonline"),
  OTEL_SERVICE_NAME: z.string().min(1).default("start-scaffold"),
});
const liveSettings = z.object({
  PUBLIC_ORIGIN: z.url(),
  AUTH_SECRET: z.string().min(32),
  DATABASE_URL: z.string().min(1),
  SMTP_HOST: z.string().min(1),
  SMTP_PORT: z.coerce.number().int().positive(),
  SMTP_USER: z.string(),
  SMTP_PASSWORD: z.string(),
  SMTP_FROM: z.email(),
});
/**
 * @param env - From the entry environment values; why: validate app settings once.
 */
export function readSettings(env: Record<string, string | undefined>) {
  const telemetry = telemetrySettings.safeParse(env);
  if (!telemetry.success)
    raise("BadSettings", { keys: telemetry.error.issues.map((issue) => issue.path.join(".")) });
  const storage = {
    side: "server",
    level: "info",
    service: telemetry.data.OTEL_SERVICE_NAME,
    traces: telemetry.data.VICTORIA_TRACES_URL,
    logs: telemetry.data.VICTORIA_LOGS_URL,
  } as const;
  const parsed = liveSettings.safeParse(env);
  if (!parsed.success)
    raise("BadSettings", { keys: parsed.error.issues.map((issue) => issue.path.join(".")) });
  const value = parsed.data;
  return {
    telemetry: storage,
    origin: value.PUBLIC_ORIGIN,
    secret: value.AUTH_SECRET,
    database: { url: value.DATABASE_URL, migrations: "drizzle" },
    mail: {
      host: value.SMTP_HOST,
      port: value.SMTP_PORT,
      user: value.SMTP_USER,
      password: value.SMTP_PASSWORD,
      from: value.SMTP_FROM,
    },
  };
}

import { z } from "zod";
import { operation, resource } from "@tinker/core";
import { auth, database } from "@/lib/tinker.server";
import { requestHeaders } from "./headers.server.ts";
import { notifications } from "./notifications.ts";
import { backendStop, requestStop } from "./lifetime.ts";
import { streamCursor } from "../protocol.ts";
import type { Stream } from "../protocol.ts";
import { raise } from "../errors.ts";
/** Cookie caches and session refresh are disabled on this long-lived request. */
const liveAccount = operation({
  label: "sync.liveAccount",
  depends: { auth, headers: requestHeaders },
  run: async ({ auth, headers }) =>
    (
      await auth.api.getSession({
        headers,
        query: { disableCookieCache: true, disableRefresh: true },
      })
    )?.user.id ?? null,
});
/** The request resource owns the returned body, including pulls after the opening operation ends. */
export const eventStream = resource({
  label: "sync.stream",
  target: "session",
  depends: { database, notifications, account: liveAccount, backendStop, requestStop },
  factory: async ({ database, notifications, account, backendStop, requestStop }, ctx) => {
    const stop = new AbortController();
    const signal = AbortSignal.any([stop.signal, backendStop, requestStop, ctx.signal]);
    let subscription: Awaited<ReturnType<typeof notifications.subscribe>> | undefined;
    let output: ReadableStreamDefaultController<Uint8Array> | undefined;
    let ended = false;
    const close = () => {
      if (ended) return;
      ended = true;
      stop.abort();
      if (subscription) notifications.close(subscription);
      output?.close();
    };
    signal.addEventListener("abort", close, { once: true });
    ctx.defer(() => {
      close();
      signal.removeEventListener("abort", close);
    });
    return {
      async open(initial: Stream.Cursor) {
        subscription = await notifications.subscribe(close);
        if (signal.aborted) {
          notifications.close(subscription);
          raise("Cancelled", {});
        }
        const changes = subscription;
        const openingWake = notifications.revision();
        const initialAccount = await account.run();
        if (initial.private && initial.private.accountId !== initialAccount)
          raise("StreamDenied", {});
        const [{ and, or, eq, gt, asc }, { event }] = await Promise.all([
          import("drizzle-orm"),
          import("./sync.schema.ts"),
        ]);
        const cursor = { ...initial, private: initial.private ? { ...initial.private } : null };
        const lease = ctx.clock.currentTimeMillis() + 30_000;
        const encoder = new TextEncoder();
        let afterWake = -1;
        const expectedAccount = cursor.private?.accountId ?? null;
        let authorizedWake = initialAccount === expectedAccount ? openingWake : -1;
        let greeted = false;
        const body = new ReadableStream<Uint8Array>(
          {
            start(controller) {
              output = controller;
              if (ended) controller.close();
              else if (signal.aborted) close();
            },
            async pull(controller) {
              try {
                while (!ended) {
                  const wake = await Promise.resolve().then(async () => {
                    if (notifications.ended(changes) || ctx.clock.currentTimeMillis() >= lease) {
                      close();
                      return notifications.revision();
                    }
                    const wake = notifications.revision();
                    if (wake !== authorizedWake) {
                      const current = await account.run();
                      authorizedWake = wake;
                      if (ended) return wake;
                      if (current !== expectedAccount) {
                        output?.enqueue(
                          encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                        );
                        close();
                      }
                    }
                    return notifications.revision();
                  });
                  if (ended) return;
                  const replayed = await Promise.resolve().then(async () => {
                    if (wake === afterWake) return false;
                    const rows = await database
                      .select()
                      .from(event)
                      .where(
                        or(
                          and(eq(event.stream, "public"), gt(event.revision, cursor.public)),
                          cursor.private
                            ? and(
                                eq(event.stream, cursor.private.accountId),
                                gt(event.revision, cursor.private.revision),
                              )
                            : undefined,
                        ),
                      )
                      .orderBy(asc(event.stream), asc(event.revision))
                      .limit(100);
                    await Promise.resolve().then(async () => {
                      const replayWake = notifications.revision();
                      if (replayWake === authorizedWake) return;
                      const current = await account.run();
                      authorizedWake = replayWake;
                      if (ended) return;
                      if (current !== expectedAccount) {
                        output?.enqueue(
                          encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                        );
                        close();
                      }
                    });
                    if (ended) return true;
                    if (!rows.length) {
                      afterWake = wake;
                      return false;
                    }
                    for (const row of rows) {
                      if (row.stream === "public") cursor.public = row.revision;
                      else if (cursor.private) cursor.private.revision = row.revision;
                    }
                    controller.enqueue(
                      encoder.encode(
                        `event: changes\nid: ${JSON.stringify(cursor)}\ndata: ${JSON.stringify({ kind: "changes", events: rows })}\n\n`,
                      ),
                    );
                    return true;
                  });
                  if (replayed) return;
                  const delivered = await Promise.resolve().then(async () => {
                    if (ended || notifications.revision() !== afterWake) return false;
                    if (!greeted) {
                      greeted = true;
                      controller.enqueue(encoder.encode(": connected\n\n"));
                      return true;
                    }
                    const waiting = new AbortController();
                    const waitingSignal = AbortSignal.any([signal, waiting.signal]);
                    try {
                      const outcome = await Promise.race([
                        notifications.wait(changes, afterWake, waitingSignal).then(() => "changed"),
                        ctx.clock.sleep(10_000, waitingSignal).then(() => "heartbeat"),
                      ]);
                      if (outcome !== "heartbeat") return false;
                      await Promise.resolve().then(async () => {
                        const heartbeatWake = notifications.revision();
                        const current = await account.run();
                        authorizedWake = heartbeatWake;
                        if (ended) return;
                        if (current !== expectedAccount) {
                          output?.enqueue(
                            encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                          );
                          close();
                        }
                      });
                      await Promise.resolve().then(async () => {
                        if (ended) return;
                        const latestWake = notifications.revision();
                        if (latestWake === authorizedWake) return;
                        const latestAccount = await account.run();
                        authorizedWake = latestWake;
                        if (ended) return;
                        if (latestAccount !== expectedAccount) {
                          output?.enqueue(
                            encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                          );
                          close();
                        }
                      });
                      if (!ended) controller.enqueue(encoder.encode(": heartbeat\n\n"));
                      return true;
                    } finally {
                      waiting.abort();
                    }
                  });
                  if (delivered) return;
                }
              } catch (error) {
                if (signal.aborted) {
                  close();
                  return;
                }
                ended = true;
                stop.abort();
                notifications.close(changes);
                controller.error(error);
              }
            },
            cancel() {
              output = undefined;
              close();
            },
          },
          { highWaterMark: 0 },
        );
        return body;
      },
    };
  },
});
export const openSync = operation({
  label: "sync.open",
  input: z.object({ cursor: streamCursor }),
  depends: { stream: eventStream },
  run: async ({ stream }, ctx) => stream.open(ctx.input.cursor),
});

import { pgTable, text, integer, jsonb, primaryKey } from "drizzle-orm/pg-core";
import type { Sync } from "../sync.ts";
export const stream = pgTable("sync_stream", {
  id: text().primaryKey(),
  revision: integer().notNull().default(0),
});
export const execution = pgTable("sync_execution", {
  id: text().primaryKey(),
  stream: text().notNull(),
  notification: jsonb().$type<unknown>(),
  result: jsonb().$type<unknown>(),
});
export const event = pgTable(
  "sync_event",
  {
    stream: text().notNull(),
    revision: integer().notNull(),
    executionId: text().notNull(),
    payload: jsonb().$type<Sync.Envelope["payload"]>().notNull(),
  },
  (row) => [primaryKey({ columns: [row.stream, row.revision] })],
);

export declare namespace Errors {
  type Payloads = {
    HttpRequestFailed: {
      method: string;
      path: string;
      cause?: { name?: string; code?: string | number };
    };
    StreamMissing: Record<string, never>;
    StreamDenied: Record<string, never>;
    StreamDisconnected: Record<string, never>;
    RetryNotAvailable: Record<string, never>;
    WriteRejected: { message: string };
    StartScopeMissing: Record<string, never>;
    Cancelled: Record<string, never>;
    BadSettings: { keys: string[] };
  };
  type Name = keyof Payloads;
  type Of<N extends Name> = Error & { kind: N; payload: Payloads[N] };
}
/**
 * @param kind - From a failed scaffold action; why: choose the managed error.
