import { resource } from "@tinker/core";
import { createIsomorphicFn } from "@tanstack/react-start";
import { telemetrySettings } from "./state.ts";
import type { Telemetry } from "./records.ts";
import { httpBackend } from "../http-backend.ts";

/** The server factory keeps storage URLs out of the browser. */
export const delivery = resource({
  label: "telemetry.delivery",
  depends: { settings: telemetrySettings.required, backend: httpBackend },
  factory: ({ settings, backend }) => {
    const send = createIsomorphicFn()
      .server(async (batch: Telemetry.Batch, signal: AbortSignal): Promise<Telemetry.Delivery> => {
        if (settings.side === "browser") return { traces: true, logs: true };
        const logs = new URL(settings.logs);
        logs.searchParams.set("_time_field", "time");
        logs.searchParams.set("_msg_field", "msg");
        logs.searchParams.set("_stream_fields", "service,side");
        const [tracesAccepted, logsAccepted] = await Promise.all([
          batch.traces.length === 0
            ? true
            : Promise.resolve().then(async () => {
                try {
                  const response = await backend(settings.traces, {
                    method: "POST",
                    headers: { "content-type": "application/json" },
                    signal,
                    redirect: "error",
                    body: JSON.stringify({
                      resourceSpans: ["server", "browser", "ssr"].flatMap((side) => {
                        const spans = batch.traces
                          .filter((span) => span.side === side)
                          .map(({ side: _side, ...span }) => span);
                        return spans.length
                          ? [
                              {
                                resource: {
                                  attributes: [
                                    {
                                      key: "service.name",
                                      value: { stringValue: settings.service },
                                    },
                                    { key: "tinker.side", value: { stringValue: side } },
                                  ],
                                },
                                scopeSpans: [{ scope: { name: "tinker.start" }, spans }],
                              },
                            ]
                          : [];
                      }),
                    }),
                  });
                  await response.body?.cancel();
                  return response.ok;
                } catch {
                  return false;
                }
              }),
          batch.logs.length === 0
            ? true
            : Promise.resolve().then(async () => {
                try {
                  const response = await backend(logs.href, {
                    method: "POST",
                    headers: { "content-type": "application/stream+json" },
                    signal,
                    redirect: "error",
                    body: batch.logs.map((record) => JSON.stringify(record)).join("\n"),
                  });
                  await response.body?.cancel();
                  return response.ok;
                } catch {
                  return false;
                }
              }),
        ]);
        return { traces: tracesAccepted, logs: logsAccepted };
      })
      .client(async (batch: Telemetry.Batch, signal: AbortSignal): Promise<Telemetry.Delivery> => {
        try {
          const response = await backend("/api/telemetry", {
            method: "POST",
            credentials: "same-origin",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(batch),
            signal,
            keepalive: true,
            redirect: "error",
          });
          await response.body?.cancel();
          return { traces: response.ok, logs: response.ok };
        } catch {
          return { traces: false, logs: false };
        }
      });
    return { send };
  },
});

import type pino from "pino";
import { createIsomorphicFn } from "@tanstack/react-start";
import { data, extension, operation, resource } from "@tinker/core";
import type { Observe } from "@tinker/core";
import { encodeValue, logRecord, telemetryBatch } from "./records.ts";
import type { Telemetry } from "./records.ts";
import { queue } from "./queue.ts";
import { telemetrySettings } from "./state.ts";
export { httpBackend } from "../http-backend.ts";
export { telemetrySettings, exportHealth } from "./state.ts";
export type { Telemetry } from "./records.ts";

export const history = data<Telemetry.Row[]>({ label: "telemetry.history", initial: [] });
/** Transfers the records to the telemetry root; callers must not edit them afterward. */
export const ingestTelemetry = operation({
  label: "telemetry.ingest",
  depends: { queue },
  input: telemetryBatch,
  run: ({ queue }, ctx) => queue.ingest(ctx.input),
});
export const flushTelemetry = operation({
  label: "telemetry.export",
  depends: { queue },
  run: ({ queue }) => queue.flush(),
});
export const telemetry = extension({
  label: "telemetry",
  hooks: {
    async start(event) {
      const owned = event.resolve(queue);
      const flush = event.controller(flushTelemetry);
      owned.start(flush.run.bind(flush));
      await event.next();
    },
    async close(event) {
      await event.resolve(queue).close();
      return event.next();
    },
  },
});

const logWriter = resource({
  label: "telemetry.writer",
  depends: { settings: telemetrySettings.required, queue },
  factory: async ({ settings, queue }, ctx) =>
    createIsomorphicFn()
      .server(async (): Promise<pino.Logger> => {
        const { default: pino } = await import("pino");
        const local = pino.destination({ dest: 1, sync: true });
        return pino(
          {
            level: settings.level,
            base: { service: settings.service, side: settings.side },
            timestamp: () => `,"time":${ctx.clock.currentTimeMillis()}`,
          },
          {
            write(line: string) {
              local.write(line);
              queue.ingest({ traces: [], logs: [logRecord.parse(JSON.parse(line))] });
            },
          },
        );
      })
      .client(async (): Promise<pino.Logger> => {
        const { default: pino } = await import("pino");
        const local = pino({ level: settings.level, browser: { asObject: true } });
        return pino({
          level: settings.level,
          base: { service: settings.service, side: settings.side },
          browser: {
            asObject: true,
            write(raw: unknown) {
              const record = logRecord.parse(raw);
              queue.ingest({ traces: [], logs: [record] });
              const write =
                record.level >= 50
                  ? local.error
                  : record.level >= 40
                    ? local.warn
                    : record.level >= 30
                      ? local.info
                      : local.debug;
              write.call(local, record);
            },
          },
        }).child({ service: settings.service, side: settings.side });
      })(),
});
export const observer = resource({
  label: "telemetry.observer",
  depends: {
    rows: history.controller,
    writer: logWriter,
    queue,
    settings: telemetrySettings.required,
  },
  factory: async ({ rows, writer, queue, settings }): Promise<Observe.Config> => ({
    history: 80,
    export(span) {
      const row = {
        id: span.spanId,
        parentId: span.parentSpanId,
        traceId: span.traceId,
        name: span.name,
        kind: span.kind,
        status: span.status ?? "open",
        duration: (span.end ?? span.start) - span.start,
      };
      rows.update((old) => [...old.slice(-79), row]);
      queue.ingest({
        traces: [
          {
            side: settings.side,
            traceId: span.traceId,
            spanId: span.spanId,
            parentSpanId: span.parentSpanId,
            flags: span.sampled ? 1 : 0,
            name: span.name.slice(0, 256),
            kind: 1,
            startTimeUnixNano: (BigInt(Math.trunc(span.start)) * 1_000_000n).toString(),
            endTimeUnixNano: (BigInt(Math.trunc(span.end ?? span.start)) * 1_000_000n).toString(),
            attributes: [
              ...Object.entries(span.attributes)
                .slice(0, 31)
                .map(([key, value]) => ({
                  key: key.slice(0, 256),
                  value: { stringValue: encodeValue(value) },
                })),
              { key: "tinker.kind", value: { stringValue: span.kind } },
            ],
            events: span.events.slice(0, 32).map((event) => ({
              name: event.name.slice(0, 256),
              timeUnixNano: (BigInt(Math.trunc(event.time)) * 1_000_000n).toString(),
              attributes: Object.entries(event.attributes)
                .slice(0, 31)
                .map(([key, value]) => ({
                  key: key.slice(0, 256),
                  value: { stringValue: encodeValue(value) },
                })),
            })),
            status:
              span.status === "failed"
                ? { code: 2, message: String(span.error).slice(0, 2048) }
                : { code: 1 },
          },
        ],
        logs: [],
      });
      writer.info({ traceId: span.traceId, spanId: span.spanId }, "core.span");
    },
    log(entry) {
      const write: pino.LogFn =
        entry.level >= 50
          ? writer.error
          : entry.level >= 40
            ? writer.warn
            : entry.level >= 30
              ? writer.info
              : writer.debug;
      write.call(
        writer,
        {
          traceId: entry.span?.traceId,
          spanId: entry.span?.spanId,
          attributes: Object.fromEntries(
            Object.entries(entry.attributes).map(([key, value]) => [
              key.slice(0, 256),
              encodeValue(value),
            ]),
          ),
        },
        entry.message.slice(0, 2048),
      );
    },
  }),
});

import { operation, tag } from "@tinker/core";
import { telemetryBatch } from "./records.ts";
import type { Telemetry } from "./records.ts";
import { backendStop, requestStop } from "../backend/lifetime.ts";
import { raise } from "../errors.ts";

/** Borrowed from the backend telemetry root. Requests neither create nor close that owner. */
export const browserTelemetry = tag<(batch: Telemetry.Batch) => Promise<void>>({
  label: "telemetry.browserIngest",
});
/** A live host binds its public origin; null is the isolated localhost/HTTPS preview proof. */
export const telemetryOrigin = tag<string | null>({ label: "telemetry.origin" });
export const receiveTelemetry = operation({
  label: "telemetry.receive",
  depends: {
    ingest: browserTelemetry.required,
    backendStop: backendStop.required,
    requestStop: requestStop.required,
  },
  input: telemetryBatch,
  run: async ({ ingest, backendStop, requestStop }, ctx) => {
    if (backendStop.aborted || requestStop.aborted || ctx.signal.aborted) raise("Cancelled", {});
    await ingest(ctx.input);
  },
});

import { resource } from "@tinker/core";
import type { Telemetry } from "./records.ts";
import { delivery } from "./delivery.ts";
import { telemetrySettings, exportHealth } from "./state.ts";

/** Retains failed records within count and byte bounds; this resource owns every promise. */
export const queue = resource({
  label: "telemetry.queue",
  target: "scope",
  depends: { settings: telemetrySettings.required, health: exportHealth.controller, delivery },
  factory: ({ settings, health, delivery }, ctx) => {
    let records: (
      | { kind: "trace"; value: Telemetry.Span }
      | { kind: "log"; value: Telemetry.Log }
    )[] = [];
    let queueBytes = 0;
    let dropped = 0;
    let timer: Promise<void> | undefined;
    let pending: Promise<void> | undefined;
    const stopTimer = new AbortController();
    const stopRequests = new AbortController();
    let state: "open" | "closing" | "closed" = "open";
    let publishing = true;
    let failed = false;
    const owned = {
      ingest(batch: Telemetry.Batch) {
        const incoming: typeof records = [
          ...batch.traces.map((value) => ({ kind: "trace" as const, value })),
          ...batch.logs.map((value) => ({ kind: "log" as const, value })),
        ];
        for (const record of incoming) {
          const recordBytes = new TextEncoder().encode(JSON.stringify(record.value)).byteLength;
          if (
            [
              state === "closed",
              recordBytes > 48_000,
              records.length >= 512,
              queueBytes + recordBytes > 1_048_576,
            ].includes(true)
          ) {
            dropped++;
          } else {
            records.push(record);
            queueBytes += recordBytes;
          }
          if (publishing) {
            const previous = health.get();
            health.set(
              previous.kind === "failed"
                ? { ...previous, pending: records.length, dropped }
                : { kind: pending ? "sending" : "queued", pending: records.length, dropped },
            );
          }
        }
      },
      start(flush: () => Promise<void>) {
        if (settings.side !== "ssr")
          timer = Promise.resolve().then(async () => {
            while (!stopTimer.signal.aborted) {
              try {
                await ctx.clock.sleep(1000, stopTimer.signal);
              } catch (error) {
                if (!stopTimer.signal.aborted) throw error;
                return;
              }
              if (!stopTimer.signal.aborted) await flush();
            }
          });
      },
      flush(): Promise<void> {
        return (pending ??= Promise.resolve()
          .then(async () => {
            if (state === "closed" || !records.length) return;
            let bytes = 0;
            const retained = records.filter((record, index) => {
              const size = new TextEncoder().encode(JSON.stringify(record.value)).byteLength;
              if (index >= 64 || bytes + size > 48_000) return false;
              bytes += size;
              return true;
            });
            const batch: Telemetry.Batch = {
              traces: retained
                .filter((record) => record.kind === "trace")
                .map((record) => record.value),
              logs: retained
                .filter((record) => record.kind === "log")
                .map((record) => record.value),
            };
            if (publishing)
              health.set({ kind: "sending", pending: records.length, dropped: dropped });
            const request = new AbortController();
            const deadline = new AbortController();
            const alarm = Promise.resolve().then(async () => {
              try {
                await ctx.clock.sleep(750, deadline.signal);
                request.abort();
              } catch (error) {
                if (!deadline.signal.aborted) throw error;
              }
            });
            let result: Telemetry.Delivery;
            try {
              result = await delivery.send(
                batch,
                AbortSignal.any([request.signal, stopRequests.signal]),
              );
            } finally {
              deadline.abort();
              await alarm;
            }
            const accepted = new Set(
              retained.filter((record) => (record.kind === "trace" ? result.traces : result.logs)),
            );
            records = records.filter((record) => !accepted.has(record));
            queueBytes = records.reduce(
              (sum, record) =>
                sum + new TextEncoder().encode(JSON.stringify(record.value)).byteLength,
              0,
            );
            failed = !result.traces || !result.logs;
            if (publishing)
              health.set(
                !failed
                  ? {
                      kind: records.length ? "queued" : "idle",
                      pending: records.length,
                      dropped: dropped,
                    }
                  : {
                      kind: "failed",
                      failure: "Telemetry storage did not accept the batch",
                      pending: records.length,
                      dropped: dropped,
                    },
              );
          })
          .finally(() => {
            pending = undefined;
          }));
      },
      async close() {
        if (state !== "open") return;
        state = "closing";
        publishing = false;
        stopTimer.abort();
        const deadline = new AbortController();
        const alarm = Promise.resolve().then(async () => {
          try {
            await ctx.clock.sleep(1500, deadline.signal);
            stopRequests.abort();
          } catch (error) {
            if (!deadline.signal.aborted) throw error;
          }
        });
        try {
          await timer;
          while (records.length && !stopRequests.signal.aborted) {
            await owned.flush();
            if (failed) break;
          }
        } finally {
          state = "closed";
          stopRequests.abort();
          deadline.abort();
          await alarm;
          dropped += records.length;
          records = [];
          queueBytes = 0;
          if (publishing) health.set({ kind: "closed", pending: 0, dropped: dropped });
        }
      },
    };
    ctx.defer(() => owned.close());
    return owned;
  },
});

import { z } from "zod";

const attribute = z.strictObject({
  key: z.string().max(256),
  value: z.strictObject({ stringValue: z.string().max(2048) }),
});
const span = z.strictObject({
  side: z.enum(["server", "browser", "ssr"]),
  traceId: z
    .string()
    .regex(/^[0-9a-f]{32}$/)
    .refine((id) => /[1-9a-f]/.test(id)),
  spanId: z
    .string()
    .regex(/^[0-9a-f]{16}$/)
    .refine((id) => /[1-9a-f]/.test(id)),
  parentSpanId: z
    .string()
    .regex(/^[0-9a-f]{16}$/)
    .optional(),
  flags: z.literal(0).or(z.literal(1)),
  name: z.string().max(256),
  kind: z.literal(1),
  startTimeUnixNano: z.string().regex(/^\d{1,20}$/),
  endTimeUnixNano: z.string().regex(/^\d{1,20}$/),
  attributes: z.array(attribute).max(32),
  events: z
    .array(
      z.strictObject({
        name: z.string().max(256),
        timeUnixNano: z.string().regex(/^\d{1,20}$/),
        attributes: z.array(attribute).max(32),
      }),
    )
    .max(32),
  status: z.strictObject({
    code: z.literal(1).or(z.literal(2)),
    message: z.string().max(2048).optional(),
  }),
});
export const logRecord = z.strictObject({
  time: z.number().int().nonnegative(),
  level: z.number().int().min(10).max(60),
  msg: z.string().max(2048),
  service: z.string().min(1).max(128),
  side: z.enum(["server", "browser", "ssr"]),
  traceId: z
    .string()
    .regex(/^[0-9a-f]{32}$/)
    .optional(),
  spanId: z
    .string()
    .regex(/^[0-9a-f]{16}$/)
    .optional(),
  attributes: z.record(z.string().max(256), z.string().max(2048)).optional(),
});
export const telemetryBatch = z
  .strictObject({ traces: z.array(span).max(64), logs: z.array(logRecord).max(64) })
  .refine((batch) => batch.traces.length + batch.logs.length <= 64);

export declare namespace Telemetry {
  type Span = z.infer<typeof span>;
  type Log = z.infer<typeof logRecord>;
  type Batch = z.infer<typeof telemetryBatch>;
  type Side = Log["side"];
  type Row = {
    id: string;
    parentId: string | undefined;
    traceId: string;
    name: string;
    kind: string;
    status: string;
    duration: number;
  };
  type Health = { pending: number; dropped: number } & (
    | { kind: "idle" | "queued" | "sending" | "closed" }
    | { kind: "failed"; failure: string }
  );
  type Settings = { side: Side; service: string; level: "info" | "debug" | "warn" | "error" } & (
    | { side: "server" | "ssr"; traces: string; logs: string }
    | { side: "browser" }
  );
  type Delivery = { traces: boolean; logs: boolean };
}

/** Core attributes may contain bigint or cycles; one bad field must not lose its record.
 * @param value - From a span or log attribute; why: bound and safely encode its wire value.
 */
export function encodeValue(value: unknown): string {
  if (typeof value === "bigint") return value.toString().slice(0, 2048);
  try {
    return (
      JSON.stringify(value, (_key, entry: unknown) =>
        typeof entry === "bigint" ? entry.toString() : entry,
      ) ?? "undefined"
    ).slice(0, 2048);
  } catch {
    return "[Unserializable]";
  }
}

import { data, tag } from "@tinker/core";
import type { Telemetry } from "./records.ts";
export const frontendSpans = tag<() => Telemetry.Row[]>({ label: "frontend.spans" });
export const exportHealth = data<Telemetry.Health>({
  label: "telemetry.exportHealth",
  initial: { kind: "idle", pending: 0, dropped: 0 },
});
export const telemetrySettings = tag<Telemetry.Settings>({ label: "telemetry.settings" });
